def generate_timer_card(remaining, elapsed, total, answered, total_q):
    """SMALLER TIMER CARD with moving yellow progress bar - LOVED VERSION"""
    W,H = 1080, 500
    img = Image.new("RGB", (W,H), BRAND["NAVY"])
    draw = ImageDraw.Draw(img)
    # Background dots
    for i in range(0, W, 150):
        for j in range(0, H, 150):
            draw.ellipse((i-10, j-10, i+10, j+10), fill=BRAND["LIGHT_NAVY"])
    # Real logo small top left
    small_logo = get_embedded_logo(60)
    img.paste(small_logo, (40, 30), small_logo)
    draw.text((120, 40), "VIDYASHALA", fill=BRAND["WHITE"], font=load_font(18, True))
    draw.text((120, 62), "LIVE TIMER", fill=BRAND["YELLOW"], font=load_font(14, True))
    # Timer pill top right - white with red dot
    mins = int(remaining // 60)
    secs = int(remaining % 60)
    timer_text = f"⏱ {mins:02d}:{secs:02d} LEFT"
    timer_bg = BRAND["WHITE"] if remaining > 60 else (255,220,220)
    tw = draw.textlength(timer_text, font=load_font(20, True)) + 80
    x2 = W-40
    x1 = x2 - tw
    draw.rounded_rectangle((x1,35,x2,95), radius=20, fill=timer_bg)
    dot_color = BRAND["RED"] if remaining <=60 else (255,59,48)
    draw.ellipse((x1+18, 52, x1+34, 68), fill=dot_color)
    draw.text((x1+48,65), timer_text, fill=BRAND["NAVY"], font=load_font(20, True), anchor="lm")
    # Center info
    mins_e = int(elapsed // 60)
    secs_e = int(elapsed % 60)
    draw.text((W//2, 140), f"Total: 07:00 | Elapsed: {mins_e:02d}:{secs_e:02d} | Answered: {answered}/{total_q}", fill=BRAND["WHITE"], font=load_font(20, True), anchor="mm")
    # MOVING YELLOW PROGRESS BAR - LOVED VERSION
    bar_w = 800
    bar_h = 16
    bx1 = W//2 - bar_w//2
    by1 = 200
    # Track
    draw.rounded_rectangle((bx1, by1, bx1+bar_w, by1+bar_h), radius=8, fill=(255,255,255,30))
    # Fill - moving yellow
    progress = elapsed / TOTAL_QUIZ_TIME
    progress = min(progress, 1.0)
    fill_w = int(bar_w * progress)
    bar_color = BRAND["YELLOW"] if remaining>60 else BRAND["RED"]
    if fill_w>0:
        draw.rounded_rectangle((bx1, by1, bx1+fill_w, by1+bar_h), radius=8, fill=bar_color)
    # Percentage
    draw.text((W//2, by1+40), f"{int(progress*100)}% Completed", fill=BRAND["YELLOW"], font=load_font(18, True), anchor="mm")
    # Bottom stats
    draw.rounded_rectangle((W//2-250, 300, W//2+250, 350), radius=16, fill=BRAND["WHITE"])
    draw.text((W//2, 325), f"⏱ Auto-submit at 00:00 | +1 / -0.25 / 0", fill=BRAND["NAVY"], font=load_font(16, True), anchor="mm")
    # Real logo watermark bottom right
    tiny = get_embedded_logo(30)
    img.paste(tiny, (W-60, H-40), tiny)
    buf = io.BytesIO(); img.save(buf, format="PNG"); buf.seek(0); return buf

